// ClientGatewayServiceServer is the server API for ClientGatewayService service.
// All implementations must embed UnimplementedClientGatewayServiceServer
// for forward compatibility.
//
// ClientGatewayService describes the authenticated REST API surface that the
// web frontend talks to via api-client at /api/v2/*.
//
// Auth is handled by gateway middleware — the user_id is injected from the
// Firebase token, NEVER sent by the client. Request messages here reflect
// what the frontend actually sends (no user_id fields).
type ClientGatewayServiceServer interface {
	// ===================== User Profile =====================
	GetProfile(context.Context, *EmptyRequest) (*user.UserProfile, error)
	UpdateProfile(context.Context, *UpdateProfileGatewayRequest) (*user.UserProfile, error)
	DeleteSelf(context.Context, *EmptyRequest) (*emptypb.Empty, error)
	// ===================== Integrations =====================
	ListIntegrations(context.Context, *EmptyRequest) (*user.UserIntegrations, error)
	GetIntegration(context.Context, *ProviderRequest) (*GetIntegrationGatewayResponse, error)
	SetIntegration(context.Context, *SetIntegrationGatewayRequest) (*emptypb.Empty, error)
	DeleteIntegration(context.Context, *ProviderRequest) (*emptypb.Empty, error)
	OAuthConnect(context.Context, *ProviderRequest) (*OAuthConnectResponse, error)
	// ===================== Connection Actions =====================
	ConnectionAction(context.Context, *ConnectionActionGatewayRequest) (*emptypb.Empty, error)
	ListConnectionActivities(context.Context, *ListConnectionActivitiesGatewayRequest) (*ListSourceActivitiesGatewayResponse, error)
	BackfillConnectionActivities(context.Context, *BackfillConnectionActivitiesGatewayRequest) (*BackfillActivitiesGatewayResponse, error)
	// ===================== Counters =====================
	ListCounters(context.Context, *EmptyRequest) (*ListCountersGatewayResponse, error)
	UpdateCounter(context.Context, *UpdateCounterGatewayRequest) (*user.Counter, error)
	DeleteCounter(context.Context, *CounterNameRequest) (*emptypb.Empty, error)
	// ===================== Booster Data =====================
	GetBoosterData(context.Context, *EmptyRequest) (*GetBoosterDataGatewayResponse, error)
	SetBoosterData(context.Context, *SetBoosterDataGatewayRequest) (*emptypb.Empty, error)
	DeleteBoosterData(context.Context, *BoosterIdRequest) (*emptypb.Empty, error)
	// ===================== Personal Records =====================
	ListPersonalRecords(context.Context, *EmptyRequest) (*ListPersonalRecordsGatewayResponse, error)
	SetPersonalRecord(context.Context, *SetPersonalRecordGatewayRequest) (*user.PersonalRecord, error)
	DeletePersonalRecord(context.Context, *RecordTypeRequest) (*emptypb.Empty, error)
	// ===================== Plugin Defaults =====================
	ListPluginDefaults(context.Context, *EmptyRequest) (*ListPluginDefaultsGatewayResponse, error)
	SetPluginDefaults(context.Context, *SetPluginDefaultsGatewayRequest) (*emptypb.Empty, error)
	DeletePluginDefaults(context.Context, *PluginIdRequest) (*emptypb.Empty, error)
	// ===================== Auth Email =====================
	SendVerificationEmail(context.Context, *EmptyRequest) (*emptypb.Empty, error)
	SendEmailChangeVerification(context.Context, *SendEmailChangeGatewayRequest) (*emptypb.Empty, error)
	SendPasswordReset(context.Context, *SendPasswordResetGatewayRequest) (*emptypb.Empty, error)
	// ===================== Mobile Sync =====================
	MobileSync(context.Context, *EmptyRequest) (*emptypb.Empty, error)
	// ===================== Pipelines =====================
	ListPipelines(context.Context, *EmptyRequest) (*ListPipelinesGatewayResponse, error)
	GetPipeline(context.Context, *PipelineIdRequest) (*pipeline.PipelineConfig, error)
	CreatePipeline(context.Context, *CreatePipelineGatewayRequest) (*pipeline.PipelineConfig, error)
	UpdatePipeline(context.Context, *UpdatePipelineGatewayRequest) (*pipeline.PipelineConfig, error)
	DeletePipeline(context.Context, *PipelineIdRequest) (*emptypb.Empty, error)
	ListPipelineRuns(context.Context, *ListPipelineRunsGatewayRequest) (*ListPipelineRunsGatewayResponse, error)
	GetPipelineRun(context.Context, *GetPipelineRunGatewayRequest) (*pipeline.PipelineRun, error)
	ListSourceActivities(context.Context, *ListSourceActivitiesGatewayRequest) (*ListSourceActivitiesGatewayResponse, error)
	BackfillActivities(context.Context, *BackfillActivitiesGatewayRequest) (*BackfillActivitiesGatewayResponse, error)
	SubmitInput(context.Context, *SubmitInputGatewayRequest) (*emptypb.Empty, error)
	CancelPipeline(context.Context, *CancelPipelineGatewayRequest) (*emptypb.Empty, error)
	CancelPipelineRun(context.Context, *CancelPipelineRunGatewayRequest) (*emptypb.Empty, error)
	RepostActivity(context.Context, *RepostActivityGatewayRequest) (*emptypb.Empty, error)
	// ===================== Activities =====================
	ListActivities(context.Context, *ListActivitiesGatewayRequest) (*ListActivitiesGatewayResponse, error)
	GetActivity(context.Context, *ActivityIdRequest) (*activity.StandardizedActivity, error)
	// ListResolvedActivities returns a page of resolved activities, each with per-field
	// provenance, for the activity list / editing surface.
	ListResolvedActivities(context.Context, *ListResolvedActivitiesGatewayRequest) (*ListResolvedActivitiesGatewayResponse, error)
	// GetResolvedActivity returns a single resolved activity (source → enricher runs →
	// user overlay) with per-field provenance for the activity detail / editing page.
	GetResolvedActivity(context.Context, *ActivityIdRequest) (*activity.ResolvedActivity, error)
	// RefreshActivitySource re-pulls the activity from its source and refreshes the
	// immutable source layer of the persisted record, returning the resolved activity.
	RefreshActivitySource(context.Context, *ActivityIdRequest) (*activity.StandardizedActivity, error)
	// UpdateActivity writes the user-edit overlay for the given fields (only those named
	// in update_mask are applied) and returns the resolved activity with the edit applied.
	// The immutable source and append-only enricher layers are never modified.
	UpdateActivity(context.Context, *UpdateActivityGatewayRequest) (*activity.StandardizedActivity, error)
	// ResendActivity re-resolves the activity and re-pushes the resolved result to its
	// configured destinations. Enrichers are not re-run; destinations that already have
	// the activity are updated in place rather than duplicated.
	ResendActivity(context.Context, *ActivityIdRequest) (*emptypb.Empty, error)
	// InvokeEnricher re-runs a single enricher out-of-band and records a proposed
	// enricher-run layer (propose → accept/dismiss). Returns the proposal and a preview.
	InvokeEnricher(context.Context, *InvokeEnricherGatewayRequest) (*InvokeEnricherGatewayResponse, error)
	// AcceptProposedEnricherRun applies a proposed enricher-run layer; returns the resolved activity.
	AcceptProposedEnricherRun(context.Context, *ProposedEnricherRunGatewayRequest) (*activity.StandardizedActivity, error)
	// DismissProposedEnricherRun drops a proposed enricher-run layer without applying it.
	DismissProposedEnricherRun(context.Context, *ProposedEnricherRunGatewayRequest) (*emptypb.Empty, error)
	DeleteActivity(context.Context, *ActivityIdRequest) (*emptypb.Empty, error)
	GetActivityStats(context.Context, *EmptyRequest) (*GetActivityStatsGatewayResponse, error)
	// ===================== Showcases =====================
	ListShowcases(context.Context, *EmptyRequest) (*ListShowcasesGatewayResponse, error)
	GetShowcase(context.Context, *ShowcaseIdRequest) (*activity.ShowcasedActivity, error)
	CreateShowcase(context.Context, *CreateShowcaseGatewayRequest) (*activity.ShowcasedActivity, error)
	UpdateShowcase(context.Context, *UpdateShowcaseGatewayRequest) (*activity.ShowcasedActivity, error)
	DeleteShowcase(context.Context, *ShowcaseIdRequest) (*emptypb.Empty, error)
	GenerateShowcaseImages(context.Context, *ShowcaseIdRequest) (*emptypb.Empty, error)
	// ===================== Showcase Management =====================
	GetShowcasePreferences(context.Context, *EmptyRequest) (*activity.ShowcaseProfile, error)
	UpdateShowcasePreferences(context.Context, *UpdateShowcasePreferencesGatewayRequest) (*activity.ShowcaseProfile, error)
	GetShowcaseSettings(context.Context, *EmptyRequest) (*GetShowcaseSettingsGatewayResponse, error)
	UpdateShowcaseSettings(context.Context, *UpdateShowcaseSettingsGatewayRequest) (*activity.ShowcaseProfile, error)
	UpdateShowcaseSlug(context.Context, *UpdateShowcaseSlugGatewayRequest) (*UpdateShowcaseSlugGatewayResponse, error)
	AddShowcaseEntry(context.Context, *ShowcaseEntryRequest) (*emptypb.Empty, error)
	RemoveShowcaseEntry(context.Context, *ShowcaseEntryRequest) (*emptypb.Empty, error)
	GetShowcaseProfilePictureUploadUrl(context.Context, *GetPictureUploadUrlGatewayRequest) (*GetPictureUploadUrlGatewayResponse, error)
	UpdateRoundupSettings(context.Context, *UpdateRoundupSettingsGatewayRequest) (*activity.ShowcaseProfile, error)
	RecomputeRoundup(context.Context, *RecomputeRoundupGatewayRequest) (*activity.ShowcaseRoundup, error)
	GetActivityPhotoUploadUrl(context.Context, *GetActivityPhotoUploadUrlGatewayRequest) (*GetActivityPhotoUploadUrlGatewayResponse, error)
	// ===================== FIT File Parse =====================
	ParseFitFile(context.Context, *ParseFitFileGatewayRequest) (*activity.StandardizedActivity, error)
	// ===================== Exercise Library =====================
	GetExerciseLibrary(context.Context, *GetExerciseLibraryGatewayRequest) (*GetExerciseLibraryGatewayResponse, error)
	// ===================== Repost Variants =====================
	RepostMissedDestination(context.Context, *RepostVariantGatewayRequest) (*RepostGatewayResponse, error)
	RepostRetryDestination(context.Context, *RepostVariantGatewayRequest) (*RepostGatewayResponse, error)
	RepostFullPipeline(context.Context, *RepostVariantGatewayRequest) (*RepostGatewayResponse, error)
	// ===================== Pipeline Run Payloads =====================
	GetPipelineRunPayload(context.Context, *GetPipelineRunPayloadGatewayRequest) (*GetPipelineRunPayloadGatewayResponse, error)
	// ExportPipelineRun returns a signed URL to a per-run ZIP (enriched + payload
	// JSON and the raw FIT file, where still retained). Replaces the single-JSON
	// payload download used by the activity detail page's Export button.
	ExportPipelineRun(context.Context, *ExportPipelineRunGatewayRequest) (*ExportPipelineRunGatewayResponse, error)
	mustEmbedUnimplementedClientGatewayServiceServer()
}

